def upload_payload(payload, service_endpoint_uri, separate_process):
    payload_uploaded = None
    if payload:
        if not separate_process:
            telemetry_core.upload(payload, service_endpoint_uri)
        else:
            subprocess.Popen([sys.executable, os.path.realpath(telemetry_core.__file__),
                              payload, service_endpoint_uri])
        payload_uploaded = payload
    return payload_uploaded

def configure_and_update_options(options):
    if options.dac_connection and options.server and not \
            options.server.lower().startswith("admin:"):
        options.server = "admin:" + options.server

    if not options.integrated_auth:
        if not options.username:
            options.username = input(u'Username (press enter for sa):') or u'sa'
        if not options.password:
            pw = getpass.getpass()
            if pw is not None:
                pw = pw.replace('\r', '').replace('\n', '')
            options.password = pw
